with d as (select value r from jsonb_array_elements($q$[{"notes":["Make a double batch, it tastes better the next day when the flavours have settled. Keeps in the fridge for 3 days.","Don't have makrut lime leaves? A squeeze of fresh lime juice works, but the leaves are worth hunting for.","Use whatever vegetables are cheap at the market: zucchini, cabbage, or even frozen mixed vegetables all work."],"id":"efd7a00b-c0ef-4309-8c1f-12c9e3e590b4"},{"notes":["Make ahead: form the kebabs up to 2 hours ahead and keep in the fridge covered.","Swap: lamb mince works beautifully here, use the same amount and follow the same method.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Put the mince in a bowl with the minced onion, garlic, ginger and green chilli. Add the cumin, coriander, garam masala and chilli powder. Crack in the egg, season with salt and pepper, and mix gently with your hands until just combined, don't overwork it or the kebabs will be tough."},{"text":"Wet your hands with water and divide the mixture into 8 equal portions. Mould each portion around a metal skewer (or flat wooden skewer soaked in water), pressing gently to form a long, even kebab about 15 cm long."},{"text":"Heat the oil in a large frying pan or griddle over medium-high heat until it's smoking. Working in batches if needed, lay the kebabs in the pan and cook without moving them for 2–3 minutes until darkly charred on the bottom."},{"text":"Turn the kebabs and cook the other side for another 2–3 minutes until charred and cooked through. Transfer to a plate."},{"text":"Serve hot with lime wedges and fresh coriander."}],"id":"e1de9256-25fd-40a4-bcff-6d2a2d23e08d"},{"notes":["This adobo keeps well in the fridge for 3 days. The flavour deepens overnight.","For a less rich version, use light coconut milk instead of full-fat.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"ab981a67-0ed2-4492-b79d-71ba7a40b35f"},{"notes":["Make it ahead: Toast the farofa in bulk and store it in an airtight container for up to 4 days. Warm it in a dry pan before serving.","Swap the sausage for bacon, chorizo, or diced leftover churrasco meat.","Serve with grilled meat, rice and beans, this is the trifecta of a proper churrasco plate.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Heat a large frying pan over medium-high heat. Cook the diced linguiça until the fat renders and it's golden, about 5 minutes. Push to the side and add the diced onion, cooking until soft, about 3 minutes."},{"text":"Add the minced garlic and cook, stirring, until fragrant, about 1 minute."},{"text":"Push everything to the side of the pan. Crack the eggs into the empty space and scramble gently until just cooked through, then stir everything together, about 2 minutes."},{"text":"Add the cassava flour in three stages, stirring well after each addition to avoid lumps. Let it toast between each addition, about 2 minutes per stage. It should be golden and smell nutty."},{"text":"Stir through the spring onion and fresh coriander. Taste and season with salt and pepper. Serve warm, this is best eaten straight from the pan at a churrasco."}],"id":"fd093fe3-951b-4041-9984-7ecec61ba2e4"},{"notes":["Tarte tatin is best served warm or at room temperature on the day it is made, though it can be gently reheated. Once cooked, do not refrigerate, the pastry will lose its crispness.","The apples can be prepared an hour ahead; keep them in a bowl of lemon water to prevent browning, then pat dry before arranging in the pan.","If your pan handle is not ovenproof, wrap it in foil before the tart goes into the oven."],"steps":[{"text":"Heat your oven to 200°C. Have a 25 cm ovenproof frying pan ready."},{"text":"Sprinkle the caster sugar evenly over the base of the pan. Place over medium heat and watch as it begins to melt at the edges. Resist the urge to stir; instead, tilt the pan gently so the unmelted sugar slides into the liquid. When all the sugar has dissolved and turned a deep amber, about 8 minutes, remove from heat. It should smell like caramel, nutty and rich."},{"text":"Working quickly, dot the 60 g butter over the caramel in small pieces. Stir in the vanilla extract."},{"text":"Arrange the apple halves cut-side up in concentric circles, starting at the outside and working towards the centre. They will fit snugly and overlap slightly. The apples will release their juice and seem to fill the pan; this is normal."},{"text":"Return the pan to medium heat and cook, without stirring, for 15 minutes. The apples will soften and the caramel will darken further. Tilt the pan occasionally to ensure even cooking."},{"text":"Roll out the puff pastry to a circle slightly larger than the pan. Lay it over the apples, tucking the edges down inside the pan. If the handle is not ovenproof, wrap it in foil."},{"text":"Bake for 20 to 25 minutes, until the pastry is golden and puffed. The edges will brown before the centre, this is fine."},{"text":"Remove from the oven and let rest for 5 minutes. Place a serving plate over the pan, then quickly and confidently invert the tart onto the plate. If any apples stick, gently replace them. Serve warm or at room temperature."}],"id":"2cac5cb1-f442-4cfd-a068-22fdc4f41b42"},{"notes":["Make the ragù the day before and reheat gently. It improves overnight.","If you can't find pork shoulder, beef chuck works just as well.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages).","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"steps":[{"text":"Heat the oil in a large, heavy-bottomed pot over medium-high heat. Working in batches, brown the pork on all sides, don't crowd the pan. Set aside, about 10 minutes total."},{"text":"Lower the heat to medium. Add the carrot, celery and onion to the same pot and cook, stirring, until soft and golden, about 12 minutes. This is your soffritto; don't skip it."},{"text":"Return the pork to the pot. Pour in the wine and let it bubble away, scraping up the brown bits, about 2 minutes. Add the tomatoes, stock and bay leaves. Stir."},{"text":"Bring to a gentle simmer. Partially cover and cook for 3 hours, stirring occasionally. The ragù is done when the meat falls apart and the sauce is thick and dark. Season with salt and pepper."},{"text":"Twenty minutes before serving, bring a large pot of salted water to a boil. Cook the pappardelle until al dente, about 3 minutes for fresh pasta. Reserve a cup of pasta water."},{"text":"Drain the pappardelle and add directly to the ragù. Toss, adding pasta water a splash at a time until the sauce coats the ribbon. Serve with grated Parmesan."}],"id":"dddaebcc-b1a0-4d57-a3ad-0bd3ae2e3376"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Bring a large pot of water to the boil. Add the egg noodles and cook for 2 minutes until just softened but still a little firm, they'll cook a bit more in the pan. Drain well in a colander."},{"text":"Heat 1 tbsp of the neutral oil in a large wok or frying pan over high heat. Add the chicken and cook, stirring, for 4 to 5 minutes until cooked through. Transfer to a plate."},{"text":"Add the remaining oil to the pan. Add the garlic and cook, stirring, for 30 seconds until fragrant. Add the spring onions and choy sum, and stir-fry for 2 minutes until the choy sum is tender and bright."},{"text":"Return the chicken to the pan. Add the cooked noodles, soy sauce, oyster sauce and sesame oil. Toss everything together, stirring gently but constantly, for 2 minutes until heated through and well mixed. Taste and adjust the seasoning with salt and white pepper."},{"text":"Divide between bowls and top with fried shallots if you like."}],"id":"aaefd80f-5306-425b-a6a2-135dd299cc81"},{"notes":["This is best eaten fresh, the moment it comes off the stove, the broccoli stays crispest that way.","If you don't like chilli heat, leave it out or just use half a slice. It's your table."],"steps":[{"text":"Heat a large frying pan over high heat without any oil. Add the broccoli and toss it around for 5–6 minutes, stirring often, until the florets are brown and crispy on the edges and tender inside. Tip onto a plate."},{"text":"In the same frying pan, warm the olive oil over low-to-medium heat. Add the sliced garlic and chilli, stirring gently for 1–2 minutes until fragrant but not brown. The oil will flavour as it warms."},{"text":"While the oil and garlic warm, bring a pot of salted water to a boil and cook the pasta until just al dente, about 10–12 minutes."},{"text":"Drain the pasta, reserving a cup of the cooking water. Add the hot pasta to the frying pan with the garlic oil, tossing gently to coat. Add the crispy broccoli back in and toss again."},{"text":"If it looks dry, splash in a splash of the pasta water to loosen it, you want it silky, not oily. Taste and add more salt and chilli if you like. Serve straightaway."}],"id":"b11bdde5-252d-4c2e-a240-7f5dd19d2673"},{"notes":["If you don't have tamarind paste, use ½ tsp tamarind concentrate or a squeeze of lemon juice, adjust to taste.","Rasam keeps well in the fridge for 2–3 days. Reheat gently on the stove; make the tempering fresh each time for maximum crackle."],"id":"0405d447-f5db-43e3-a8e8-67f8c65a332b"},{"notes":["Make a double batch on Sunday: divide into two jars and it lasts the week. The flavour deepens after day two.","Serve cold or at room temperature with white rice and other banchan.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Blanch the calamari in boiling water for 1 minute, then drain and set aside, this stops it toughening when you stir-fry it."},{"text":"Heat the sesame oil in a large pan or wok over medium-high heat. Add the garlic and fry, stirring, for about 30 seconds until fragrant."},{"text":"Add the gochugaru and stir for another 30 seconds to bloom the spice. Pour in the soy sauce and sugar."},{"text":"Add the calamari and the white parts of the spring onion. Stir-fry for 2–3 minutes until everything is coated and heated through. Don't overcook or the squid will be rubbery."},{"text":"Remove from heat. Fold through the green parts of the spring onion and sprinkle with sesame seeds."},{"text":"Let it cool to room temperature, then transfer to a clean jar. It keeps covered in the fridge for 5 days."}],"id":"41616200-9dd3-4679-8a57-4968cba4a792"},{"notes":["Make this a day ahead and reheat gently; the flavours deepen overnight. Serve with mashed potato, crusty bread or steamed greens.","A dry Tasmanian apple cider works best, but you can use any dry cider. If you only have sweet cider on hand, reduce the honey.","Leftovers keep in the fridge for up to 4 days and freeze well for a month.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"steps":[{"text":"Heat the oven to 160°C. Pat the pork dry and season generously with salt and pepper."},{"text":"Heat the oil in a large heavy-bottomed pot or Dutch oven over medium-high heat. Working in batches, brown the pork for 2–3 minutes on each side, then set aside on a plate. Don't crowd the pan, you're looking for a good golden colour, not steam."},{"text":"In the same pot, cook the onions and garlic until the onions soften and just begin to colour, about 5 minutes. Pour in the cider, scraping up the browned bits at the bottom, and let it bubble for a minute."},{"text":"Return the pork to the pot, add the stock, thyme and bay leaves. Bring to a simmer, then cover and transfer to the oven for 2 hours, stirring occasionally."},{"text":"Add the apples and stir through. Return to the oven, uncovered, for another 30 minutes, until the pork is very tender and the apples have softened into the sauce."},{"text":"Taste and adjust the seasoning. If you like, stir through the honey for a little sweetness. Serve with crusty bread or mashed potato."}],"id":"30061f9a-f5d6-456b-aa1e-774a62057b12"},{"notes":["If you can't find shishitos, long green chillies work fine, just halve them lengthways so they cook through faster.","Make the dressing ahead of time if you like, but toss the peppers while they're still hot so they soak up the flavours."],"id":"44d159f3-ba5e-4937-988b-6210581f61c7"},{"notes":["Make ahead: Prepare the batter up to 4 hours before steaming and keep chilled. Assemble and steam when ready.","Banana leaves: If you have fresh or frozen banana leaves, wrap each portion in a leaf before steaming for that authentic texture.","This uses raw or lightly cooked egg. Use fresh, clean, uncracked eggs (pasteurised if you can get them), keep it cold, and skip it for anyone pregnant, very young, elderly or with low immunity.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Boil the 2 eggs for 8 minutes until just hard-boiled, then peel and set aside."},{"text":"In a blender, combine the drained black-eyed peas, red onion, red chillies, garlic, raw egg, oil, ginger, salt and pepper. Blend until completely smooth, 2–3 minutes; the batter should be light and silky."},{"text":"Lightly oil four small ramekins (about 200 ml each) or line four coffee cups with plastic wrap."},{"text":"Divide one-third of the batter among the ramekins. Place a hard-boiled egg in the centre of each, then top with the remaining batter until each ramekin is three-quarters full."},{"text":"Pour water into a large pot to a depth of 3 cm. Place a trivet or heat-proof saucer in the bottom. Bring to a boil until the water is bubbling steadily and steam is rising."},{"text":"Carefully place the ramekins on the trivet. Cover the pot with a lid and steam over medium heat for 40 minutes, until the moi moi is set and springs back when lightly touched. Refill the water if it falls below the level of the trivet."},{"text":"Remove from the pot and let rest for 5 minutes. Run a knife around the edge of each ramekin and turn out onto a plate (if using ramekins) or unwrap carefully. Serve warm with bread or rice."}],"id":"4677577f-ac3b-4df1-866e-4daec9f31f3e"},{"notes":["Make the filling up to 3 hours ahead and reheat gently before using. It's best warm but not piping hot when you wrap it.","Use waxy potato if floury is hard to find, it'll be a bit stickier but still work fine."],"steps":[{"text":"Boil the potato in salted water until tender, about 15 minutes. Drain well."},{"text":"While the potato cooks, heat the oil in a large pan over medium heat. Add the cumin seeds and let them crackle for 30 seconds until fragrant."},{"text":"Add the diced onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the chopped green chillies and cook for another minute, until fragrant and the chillies have softened slightly."},{"text":"Tip the hot potato into the pan and mash gently with the back of a wooden spoon, breaking it into floury pieces rather than a smooth paste. The potato should be chunky and still slightly warm."},{"text":"Mix in the salt and pepper to taste. Set aside to cool slightly before using to fill roti."}],"id":"b418fd8e-f623-47fd-916e-42f2818a0861"},{"notes":["You can prep the octopus the day before: boil it, cool, cut it, and store it in the fridge. Grill it fresh on the day.","Charring the lemon is crucial, don't skip it. The bitterness and colour make the dish.","If you can't find whole fresh octopus, use frozen. Thaw it overnight in the fridge first.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Fill a large pot with water and bring to a boil. Add the octopus, onion and bay leaves. Simmer gently for 45–60 minutes, until the octopus is tender, a fork should pierce it easily. Drain and let cool slightly."},{"text":"Cut the octopus in half lengthwise, then cut each half into 4 or 5 pieces. Pat dry with paper towel."},{"text":"Heat your grill to high until very hot and smoking lightly. Brush the octopus pieces with a little olive oil and season with salt and pepper."},{"text":"Grill the octopus for 3–4 minutes each side until charred and crispy on the outside. Transfer to a plate."},{"text":"Place the lemon halves cut-side down on the grill and char for 2–3 minutes until dark and caramelised."},{"text":"Arrange the octopus on a serving platter. Drizzle generously with olive oil, scatter with oregano, squeeze the charred lemon juice over everything and season with more salt and pepper. Serve warm."}],"id":"0874a33e-71c9-48bc-9412-f4fa844e29fd"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;